    t[3]=(float)(((LDF(pB+0x18)*LDF(pA+0x20))+(LDF(pB+0x14)*LDF(pA+0x10)))+(LDF(pB+0x10)*LDF(pA+0x0)));
    t[4]=(float)(((LDF(pB+0x14)*LDF(pA+0x14))+(LDF(pB+0x18)*LDF(pA+0x24)))+(LDF(pB+0x10)*LDF(pA+0x4)));
    t[5]=(float)(((LDF(pB+0x14)*LDF(pA+0x18))+(LDF(pB+0x18)*LDF(pA+0x28)))+(LDF(pB+0x10)*LDF(pA+0x8)));
    t[6]=(float)(((LDF(pB+0x28)*LDF(pA+0x20))+(LDF(pB+0x24)*LDF(pA+0x10)))+(LDF(pB+0x20)*LDF(pA+0x0)));
    t[7]=(float)(((LDF(pB+0x24)*LDF(pA+0x14))+(LDF(pB+0x28)*LDF(pA+0x24)))+(LDF(pB+0x20)*LDF(pA+0x4)));
    t[8]=(float)(((LDF(pB+0x24)*LDF(pA+0x18))+(LDF(pB+0x28)*LDF(pA+0x28)))+(LDF(pB+0x20)*LDF(pA+0x8)));
